document.addEventListener("DOMContentLoaded",(()=>{const e=document.querySelector("header"),t=document.querySelector("main > section:first-of-type");if(!e||!t)return;const n=undefined;new IntersectionObserver((([t])=>e.classList.toggle("transparent-section",t.boundingClientRect.bottom<=e.offsetHeight)),{rootMargin:`-${e.offsetHeight}px 0px 0px 0px`}).observe(t)}));